"""ORM models. The PostGIS `geom` columns are generated by the database from
latitude/longitude, so they are not mapped here; spatial queries use SQL."""
from __future__ import annotations

from datetime import datetime

from sqlalchemy import ForeignKey, func
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, relationship


class Base(DeclarativeBase):
    pass


class WeatherDataset(Base):
    __tablename__ = "weather_datasets"
    id: Mapped[str] = mapped_column(primary_key=True)
    name: Mapped[str]
    source: Mapped[str]
    latitude: Mapped[float]
    longitude: Mapped[float]
    time_zone: Mapped[float]
    monthly: Mapped[list] = mapped_column(JSONB)
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())


class Site(Base):
    __tablename__ = "sites"
    id: Mapped[int] = mapped_column(primary_key=True)
    name: Mapped[str]
    latitude: Mapped[float]
    longitude: Mapped[float]
    time_zone: Mapped[float]
    address: Mapped[str | None]
    building_type: Mapped[str | None]
    floor_area_m2: Mapped[float | None]
    year_built: Mapped[int | None]
    occupants: Mapped[int | None]
    ua_house: Mapped[float | None]
    notes: Mapped[str | None]
    weather_id: Mapped[str | None] = mapped_column(ForeignKey("weather_datasets.id", ondelete="SET NULL"))
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())
    scenarios: Mapped[list[Scenario]] = relationship(back_populates="site", passive_deletes=True)


class Scenario(Base):
    __tablename__ = "scenarios"
    id: Mapped[int] = mapped_column(primary_key=True)
    site_id: Mapped[int | None] = mapped_column(ForeignKey("sites.id", ondelete="CASCADE"))
    weather_id: Mapped[str | None] = mapped_column(ForeignKey("weather_datasets.id", ondelete="SET NULL"))
    name: Mapped[str]
    model: Mapped[str]
    collector: Mapped[dict] = mapped_column(JSONB)
    system: Mapped[dict] = mapped_column(JSONB)
    diagram: Mapped[dict | None] = mapped_column(JSONB(none_as_null=True))  # set when model == "diagram"
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())
    updated_at: Mapped[datetime] = mapped_column(server_default=func.now(), onupdate=func.now())
    site: Mapped[Site | None] = relationship(back_populates="scenarios")
    # Not loaded by the API (summaries are queried directly); kept for ORM completeness.
    runs: Mapped[list[Run]] = relationship(back_populates="scenario", passive_deletes=True, lazy="raise_on_sql")


class Run(Base):
    __tablename__ = "runs"
    id: Mapped[int] = mapped_column(primary_key=True)
    scenario_id: Mapped[int] = mapped_column(ForeignKey("scenarios.id", ondelete="CASCADE"))
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())
    result: Mapped[dict] = mapped_column(JSONB)  # SimulationResult without hourly
    scenario: Mapped[Scenario] = relationship(back_populates="runs")
